USE LR_itis
/*
Domain
└── Kingdom
    └── Phylum
        └── Class
            └── Order
                └── Family
                    └── Genus
                        └── Species
*/

insert into kingdom(kingdomname) values
 ('Animalia')
,('Archaea')
,('Bacteria')
,('Chromista')
,('Fungi')
,('Plantae')
,('Protozoa')

update kingdom
set kingdom_domain=domainid
from domain
where domainname=
	case
		when kingdomname='Archaea' then 'Archaea'
		when kingdomname='Bacteria' then 'Bacteria'
		else 'Eukarya'
	end
go
select domainname
	,kingdomname
from kingdom
join domain on kingdom_domain=domainid
order by domainname,kingdomname


